import React, { Component } from 'react';
import { CButton, CCard, CCardBody, CCol, CContainer, CInput, CTextarea, CRow } from '@coreui/react';
import Select from 'react-select';
import { requestHeaderGETWithAuth, requestHeaderPOSTWithAuth, requestHeaderPUTWithAuth, requestHeaderDELETEWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "ViewAction.js";

const PRIORITY_OPTIONS = [
    { value: 'P0', label: 'P0 — highest' },
    { value: 'P1', label: 'P1 — medium' },
    { value: 'P2', label: 'P2 — lowest' },
];

const STATUS_OPTIONS = [
    { value: 'TODO', label: 'TODO' },
    { value: 'WIP', label: 'WIP' },
    { value: 'DONE', label: 'DONE' },
];

const PRIORITY_COLORS = { P0: '#e53e3e', P1: '#dd6b20', P2: '#3182ce' };
const STATUS_COLORS = { TODO: '#718096', WIP: '#3182ce', DONE: '#38a169' };

// Default time-of-day applied to the start date when the user doesn't pick one.
const DEFAULT_START_TIME = '09:00';

// start_date carries a time-of-day. The UI keeps the date and time as two separate inputs
// while the API uses a single space-separated "yyyy-MM-dd HH:mm" string. These helpers split an
// API value into its date and time parts and recombine them on save. All are null/empty-safe
// and tolerate a date-only API value (back-compat with old rows).
const dateOnly = (value) => (value ? value.replace('T', ' ').split(' ')[0] : '');

const timeOnly = (value) => {
    if (!value) return '';
    const parts = value.replace('T', ' ').split(' ');
    return parts[1] ? parts[1].slice(0, 5) : '';
};

const combineDateAndTimeForApi = (datePart, timePart) => {
    if (!datePart) return null;
    const time = timePart || DEFAULT_START_TIME;
    return datePart + ' ' + time.slice(0, 5);
};

class ViewAction extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            action: null,
            error: null,
            subprograms: [],
            persons: [],
            programs: [],
            isEditing: false,
            // edit fields
            editTitle: '',
            editDescription: '',
            editPriority: 'P1',
            editStatus: 'TODO',
            editSubprogramId: '',
            editPersonId: '',
            editStartDate: '',
            editStartTime: DEFAULT_START_TIME,
            editDueDate: '',
            editTimeEstimateInHours: '',
            editComments: [],
            editNewComment: '',
            // index of the comment currently being edited inline (null = none)
            editingCommentIndex: null,
            editingCommentText: '',
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "View Action";
        this.fetchReferenceData().then(() => this.fetchAction());
        window.addEventListener('beforeunload', this.handleBeforeUnload);
    }

    componentWillUnmount() {
        window.removeEventListener('beforeunload', this.handleBeforeUnload);
    }

    // Warn the user about losing unsaved changes when leaving/reloading/closing
    // the page while the edit view is open.
    //
    // NOTE: modern browsers only honor this prompt when the page has received a
    // "sticky activation" (a real user gesture — click, keypress, etc.) during
    // this page load. They also ignore any custom message and show their own
    // generic text. The non-empty returnValue below is the most widely-supported
    // way to trigger the prompt across engines.
    handleBeforeUnload = (event) => {
        if (!this.state.isEditing) return undefined;
        const message = 'You have unsaved changes. Leave anyway?';
        event.preventDefault();
        event.returnValue = message;
        return message;
    }

    getActionId() {
        return this.props.match.params.id;
    }

    fetchReferenceData = () => {
        const userData = getUserDataFromLocalStorage();
        const subprogramPayload = JSON.stringify({ page: 1, size: 0 });
        const personPayload = JSON.stringify({ page: 1, size: 0 });
        const programPayload = JSON.stringify({ page: 1, size: 0 });

        return Promise.all([
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program/list', requestHeaderPOSTWithAuth(subprogramPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/person/list', requestHeaderPOSTWithAuth(personPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list', requestHeaderPOSTWithAuth(programPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
        ])
        .then(([subprogramsResult, personsResult, programsResult]) => {
            this.setState({
                subprograms: (subprogramsResult && subprogramsResult.data) || [],
                persons: (personsResult && personsResult.data) || [],
                programs: (programsResult && programsResult.data) || [],
            });
        })
        .catch(error => Logger(FILE_NAME, "fetchReferenceData", "ERROR", "error", error));
    }

    // Fetches a single action via GET /v1/action/{id}.
    fetchAction() {
        const id = this.getActionId();
        this.setState({ isLoaded: false, error: null });
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/action/' + id;

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            if (response.status === 404) return null;
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            const action = (result && result.data) || null;
            Logger(FILE_NAME, "fetchAction", "SUCCESS", "action", action);
            if (action) document.title = "Action #" + action.id;
            this.setState({ isLoaded: true, action, error: action ? null : 'Action not found' });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchAction", "ERROR", "error", error);
            this.setState({ isLoaded: true, error: error.message });
        });
    }

    startEditing = () => {
        const { action } = this.state;
        this.setState({
            isEditing: true,
            editTitle: action.title || '',
            editDescription: action.description || '',
            editPriority: action.priority || 'P1',
            editStatus: action.status || 'TODO',
            editSubprogramId: action.subprogramId ? String(action.subprogramId) : '',
            editPersonId: action.personId ? String(action.personId) : '',
            editStartDate: dateOnly(action.startDate),
            editStartTime: timeOnly(action.startDate) || DEFAULT_START_TIME,
            editDueDate: action.dueDate || '',
            editTimeEstimateInHours: (action.timeEstimateInHours === null || action.timeEstimateInHours === undefined) ? '' : String(action.timeEstimateInHours),
            editComments: action.comments ? [...action.comments] : [],
            editNewComment: '',
        });
    }

    cancelEditing = () => {
        if (!window.confirm('Discard your unsaved changes and leave edit mode?')) return;
        this.setState({ isEditing: false });
    }

    // Intercept the in-app "Back to Actions List" navigation while editing so
    // unsaved changes aren't silently lost (beforeunload only covers full reloads).
    handleBackToList = (event) => {
        if (this.state.isEditing && !window.confirm('Discard your unsaved changes and leave this action?')) {
            event.preventDefault();
        }
    }

    addEditComment = () => {
        const text = this.state.editNewComment.trim();
        if (!text) return;
        this.setState(prev => ({ editComments: [...prev.editComments, { comment: text }], editNewComment: '' }));
    }

    removeEditComment = (index) => {
        this.setState(prev => ({ editComments: prev.editComments.filter((_, i) => i !== index), editingCommentIndex: null }));
    }

    startEditingComment = (index) => {
        this.setState({ editingCommentIndex: index, editingCommentText: this.state.editComments[index].comment });
    }

    cancelEditingComment = () => {
        this.setState({ editingCommentIndex: null, editingCommentText: '' });
    }

    saveEditingComment = () => {
        const { editingCommentIndex, editingCommentText, editComments } = this.state;
        if (editingCommentIndex === null) return;
        const trimmed = editingCommentText.trim();
        if (!trimmed) return;
        const updated = [...editComments];
        updated[editingCommentIndex] = { ...updated[editingCommentIndex], comment: trimmed };
        this.setState({ editComments: updated, editingCommentIndex: null, editingCommentText: '' });
    }

    saveChanges = () => {
        const { action, editTitle, editDescription, editPriority, editStatus, editSubprogramId, editPersonId, editStartDate, editStartTime, editDueDate, editTimeEstimateInHours, editComments } = this.state;

        if (!editTitle.trim()) {
            alert('Title is required.');
            return;
        }

        if (editTimeEstimateInHours.trim() !== '' && (isNaN(Number(editTimeEstimateInHours)) || Number(editTimeEstimateInHours) < 0)) {
            alert('Time estimate must be a non-negative number.');
            return;
        }

        // Due date cannot be before start date (same calendar day is allowed). Compare on the
        // start date only — the time-of-day doesn't affect the day-level comparison.
        if (editStartDate && editDueDate && editDueDate < editStartDate) {
            alert('Due Date cannot be before Start Date.');
            return;
        }

        const payload = {
            title: editTitle.trim(),
            description: editDescription.trim() || null,
            priority: editPriority,
            status: editStatus,
            subprogramId: editSubprogramId ? Number(editSubprogramId) : null,
            personId: editPersonId ? Number(editPersonId) : null,
            startDate: combineDateAndTimeForApi(editStartDate, editStartTime),
            dueDate: editDueDate || null,
            timeEstimateInHours: editTimeEstimateInHours.trim() !== '' ? Math.round(Number(editTimeEstimateInHours) * 100) / 100 : null,
            comments: editComments,
        };

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/action/' + action.id;

        fetch(API_URL, requestHeaderPUTWithAuth(JSON.stringify(payload), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "saveChanges", "SUCCESS", "result", result);
            this.setState({ loadingModalState: 1, action: result.data, isEditing: false });
            setTimeout(() => this.setState({ loadingModalVisible: false, loadingModalState: 0 }), 800);
        })
        .catch(error => {
            Logger(FILE_NAME, "saveChanges", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    handleDelete = () => {
        const { action } = this.state;
        if (!window.confirm('Delete this action? This is a soft delete.')) return;

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/action/' + action.id;

        fetch(API_URL, requestHeaderDELETEWithAuth(null, userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleDelete", "SUCCESS", "result", result);
            this.setState({ loadingModalState: 1 });
            setTimeout(() => { this.setState({ loadingModalVisible: false }); window.location.hash = '#/actions'; }, 800);
        })
        .catch(error => {
            Logger(FILE_NAME, "handleDelete", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    getProgramName = (programId) => {
        const prog = this.state.programs.find(p => p.id === programId);
        return prog ? prog.name : programId;
    }

    // Builds the "<Program> / <Sub-program>" label, resolving the parent program
    // name via the programs lookup. Falls back to just the sub-program name.
    getSubprogramLabel = (subprogram) => {
        const prog = this.state.programs.find(p => p.id === subprogram.programId);
        return prog ? prog.name + ' / ' + subprogram.name : subprogram.name;
    }

    getSubprogramName = (subprogramId) => {
        if (!subprogramId) return '—';
        const p = this.state.subprograms.find(pr => pr.id === subprogramId);
        return p ? this.getSubprogramLabel(p) : subprogramId;
    }

    getPersonName = (personId) => {
        if (!personId) return '—';
        const p = this.state.persons.find(pe => pe.id === personId);
        return p ? p.name : personId;
    }

    // Highlights a date (start/due) relative to today, but only while the action
    // is NOT done — a completed action's dates are no longer actionable.
    //   past  → red
    //   today → yellow
    //   future / no date / DONE → no highlight
    // Dates are stored as plain yyyy-MM-dd, so compare on calendar day in local
    // time rather than instants.
    getDateHighlightStyle = (dateStr) => {
        const { action } = this.state;
        if (!dateStr || !action || action.status === 'DONE') return null;

        const parts = dateStr.split('-');
        if (parts.length !== 3) return null;
        const target = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
        target.setHours(0, 0, 0, 0);

        const today = new Date();
        today.setHours(0, 0, 0, 0);

        if (target < today) {
            return { background: '#fed7d7', color: '#742a2a', borderRadius: '6px', padding: '2px 8px', fontWeight: 600 };
        }
        if (target.getTime() === today.getTime()) {
            return { background: '#fefcbf', color: '#744210', borderRadius: '6px', padding: '2px 8px', fontWeight: 600 };
        }
        return null;
    }

    // Formats a plain yyyy-MM-dd date as "Mon, 2026-10-05" (weekday prefix),
    // parsing on local calendar day so the weekday matches the stored date.
    formatDateWithWeekday = (dateStr) => {
        const parts = dateStr.split('-');
        if (parts.length !== 3) return dateStr;
        const d = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
        if (isNaN(d.getTime())) return dateStr;
        return d.toLocaleDateString(undefined, { weekday: 'short' }) + ', ' + dateStr;
    }

    // Renders a date value with the relative-to-today highlight applied.
    renderDateValue = (dateStr) => {
        if (!dateStr) return <span style={styles.empty}>Not set</span>;
        const label = this.formatDateWithWeekday(dateStr);
        const highlight = this.getDateHighlightStyle(dateStr);
        return highlight ? <span style={highlight}>{label}</span> : <span>{label}</span>;
    }

    // Renders the start date, which carries a time-of-day ("yyyy-MM-dd HH:mm").
    // The relative-to-today highlight is keyed off the calendar day; the HH:mm is
    // appended after the weekday-prefixed date, e.g. "Mon, 2026-09-12 12:34".
    renderStartDateValue = (value) => {
        if (!value) return <span style={styles.empty}>Not set</span>;
        const normalized = value.replace('T', ' ');
        const datePart = normalized.split(' ')[0];
        const timePart = (normalized.split(' ')[1] || '').slice(0, 5);
        const label = this.formatDateWithWeekday(datePart) + (timePart ? ' ' + timePart : '');
        const highlight = this.getDateHighlightStyle(datePart);
        return highlight ? <span style={highlight}>{label}</span> : <span>{label}</span>;
    }

    render() {
        const { isLoaded, action, error, isEditing } = this.state;

        if (!isLoaded) return <Loading />;

        if (error || !action) {
            return (
                <div style={{ textAlign: 'center', padding: '40px', color: '#dc3545' }}>
                    <h3>Error loading action</h3>
                    <p>{error || 'Not found'}</p>
                    <a href="#/actions">← Back to Actions List</a>
                </div>
            );
        }

        return (
            <div>
                <a href="#/actions" style={{ textDecoration: 'none' }} onClick={this.handleBackToList}>
                    <CButton color="secondary" className="mb-3">← Back to Actions List</CButton>
                </a>
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="8">
                            <CCard className="p-4">
                                <CCardBody>
                                    {!isEditing ? this.renderViewMode() : this.renderEditMode()}
                                </CCardBody>
                            </CCard>
                        </CCol>
                    </CRow>
                </CContainer>
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }

    renderBadge(text, color) {
        return (
            <span style={{ background: color, color: 'white', borderRadius: '12px', padding: '2px 12px', fontWeight: 600, fontSize: '0.85em' }}>
                {text}
            </span>
        );
    }

    renderViewMode() {
        const { action } = this.state;

        return (
            <>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '12px' }}>
                    <h1 style={{ margin: 0 }}>#{action.id} — {action.title}</h1>
                    <div style={{ display: 'flex', gap: '8px', flexShrink: 0 }}>
                        <CButton color="info" onClick={() => this.fetchAction()}>🔄 Reload</CButton>
                        <CButton color="primary" onClick={this.startEditing}>✏️ Edit</CButton>
                        <CButton color="danger" onClick={this.handleDelete}>🗑️ Delete</CButton>
                    </div>
                </div>
                <div style={{ marginTop: '10px', display: 'flex', gap: '8px', alignItems: 'center' }}>
                    {this.renderBadge(action.priority, PRIORITY_COLORS[action.priority] || '#718096')}
                    {this.renderBadge(action.status, STATUS_COLORS[action.status] || '#718096')}
                </div>
                <hr />

                <div style={styles.section}>
                    <h5>📝 Description</h5>
                    <p style={{ whiteSpace: 'pre-wrap' }}>{action.description || <span style={styles.empty}>No description</span>}</p>
                </div>

                <CRow>
                    <CCol md="6" style={styles.section}>
                        <h5>📁 Sub-program</h5>
                        <p>{this.getSubprogramName(action.subprogramId)}</p>
                    </CCol>
                    <CCol md="6" style={styles.section}>
                        <h5>👽 Person</h5>
                        <p>{this.getPersonName(action.personId)}</p>
                    </CCol>
                </CRow>

                <CRow>
                    <CCol md="4" style={styles.section}>
                        <h5>🚀 Start Date &amp; Time</h5>
                        <p>{this.renderStartDateValue(action.startDate)}</p>
                    </CCol>
                    <CCol md="4" style={styles.section}>
                        <h5>📅 Due Date</h5>
                        <p>{this.renderDateValue(action.dueDate)}</p>
                    </CCol>
                    <CCol md="4" style={styles.section}>
                        <h5>⏱️ Time Estimate (hrs)</h5>
                        <p>{(action.timeEstimateInHours === null || action.timeEstimateInHours === undefined)
                            ? <span style={styles.empty}>Not set</span>
                            : action.timeEstimateInHours}</p>
                    </CCol>
                </CRow>

                <div style={styles.section}>
                    <h5>💬 Comments</h5>
                    {action.comments && action.comments.length > 0 ? (
                        <ul style={{ paddingLeft: '20px' }}>
                            {action.comments.map((c, i) => (
                                <li key={'c-' + i} style={{ marginBottom: '6px' }}>
                                    {c.createdAt && <span style={{ color: '#888', fontSize: '0.85em', marginRight: '8px' }}>{c.createdAt}</span>}
                                    {c.comment}
                                </li>
                            ))}
                        </ul>
                    ) : <p style={styles.empty}>No comments</p>}
                </div>

                <CRow>
                    <CCol md="6" style={styles.section}>
                        <h5>🕐 Created</h5>
                        <p>{action.createdOn ? new Date(action.createdOn).toLocaleString(undefined, { weekday: 'short', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric' }) : '—'}</p>
                    </CCol>
                    <CCol md="6" style={styles.section}>
                        <h5>🔄 Updated</h5>
                        <p>{action.updatedOn ? new Date(action.updatedOn).toLocaleString(undefined, { weekday: 'short', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric' }) : '—'}</p>
                    </CCol>
                </CRow>
            </>
        );
    }

    renderEditMode() {
        const { editTitle, editDescription, editPriority, editStatus, editSubprogramId, editPersonId, editStartDate, editStartTime, editDueDate, editTimeEstimateInHours, editComments, editNewComment, subprograms, persons } = this.state;

        const subprogramOptions = subprograms.map(p => ({ value: String(p.id), label: this.getSubprogramLabel(p) }));
        const personOptions = persons.map(p => ({ value: String(p.id), label: p.name }));

        return (
            <>
                <h2>✏️ Edit Action</h2>
                <hr />
                <CRow>
                    <CCol md="6">
                        <label><strong>Sub-program</strong></label>
                        <Select className="mb-3" isClearable placeholder="Optional" options={subprogramOptions}
                            value={subprogramOptions.find(o => o.value === String(editSubprogramId)) || null}
                            onChange={(opt) => this.setState({ editSubprogramId: opt ? opt.value : '' })} />
                    </CCol>
                    <CCol md="6">
                        <label><strong>Person 👽</strong></label>
                        <Select className="mb-3" isClearable placeholder="Optional" options={personOptions}
                            value={personOptions.find(o => o.value === String(editPersonId)) || null}
                            onChange={(opt) => this.setState({ editPersonId: opt ? opt.value : '' })} />
                    </CCol>
                </CRow>

                <label><strong>Title *</strong></label>
                <CInput className="mb-3" value={editTitle} onChange={(e) => this.setState({ editTitle: e.target.value })} required />

                <label><strong>Description</strong></label>
                <CTextarea className="mb-3" rows="3" value={editDescription} onChange={(e) => this.setState({ editDescription: e.target.value })} />

                <CRow>
                    <CCol md="6">
                        <label><strong>Priority *</strong></label>
                        <Select className="mb-3" options={PRIORITY_OPTIONS}
                            value={PRIORITY_OPTIONS.find(o => o.value === editPriority) || null}
                            onChange={(opt) => this.setState({ editPriority: opt ? opt.value : '' })} />
                    </CCol>
                    <CCol md="6">
                        <label><strong>Status</strong></label>
                        <Select className="mb-3" options={STATUS_OPTIONS}
                            value={STATUS_OPTIONS.find(o => o.value === editStatus) || null}
                            onChange={(opt) => this.setState({ editStatus: opt ? opt.value : 'TODO' })} />
                    </CCol>
                </CRow>

                

                <CRow>
                    <CCol md="3">
                        <label><strong>📅 Start Date</strong></label>
                        <CInput className="mb-3" type="date" value={editStartDate} onChange={(e) => this.setState({ editStartDate: e.target.value })} />
                    </CCol>
                    <CCol md="3">
                        <label><strong>🕘 Start Time</strong></label>
                        <CInput className="mb-3" type="time" value={editStartTime} onChange={(e) => this.setState({ editStartTime: e.target.value })} />
                    </CCol>
                    <CCol md="3">
                        <label><strong>🧞‍♂️ Due Date</strong></label>
                        <CInput className="mb-3" type="date" value={editDueDate} min={editStartDate || undefined} onChange={(e) => this.setState({ editDueDate: e.target.value })} />
                    </CCol>
                    <CCol md="3">
                        <label><strong>⏱️ Time Estimate (hrs)</strong></label>
                        <CInput className="mb-3" type="number" min="0" step="0.01" placeholder="Optional"
                            value={editTimeEstimateInHours}
                            onChange={(e) => this.setState({ editTimeEstimateInHours: e.target.value })} />
                    </CCol>
                </CRow>

                <label><strong>Comments</strong></label>
                {editComments.length > 0 && (
                    <ul style={{ paddingLeft: '20px' }}>
                        {editComments.map((c, i) => (
                            <li key={'ec-' + i} style={{ marginBottom: '6px' }}>
                                {this.state.editingCommentIndex === i ? (
                                    <div style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
                                        <CInput
                                            value={this.state.editingCommentText}
                                            onChange={(e) => this.setState({ editingCommentText: e.target.value })}
                                            onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); this.saveEditingComment(); } if (e.key === 'Escape') { this.cancelEditingComment(); } }}
                                            style={{ flex: 1 }}
                                            autoFocus
                                        />
                                        <CButton color="success" size="sm" onClick={this.saveEditingComment} title="Save">✓</CButton>
                                        <CButton color="secondary" size="sm" onClick={this.cancelEditingComment} title="Cancel">✕</CButton>
                                    </div>
                                ) : (
                                    <>
                                        {c.createdAt && <span style={{ color: '#888', fontSize: '0.85em', marginRight: '8px' }}>{c.createdAt}</span>}
                                        {c.comment}
                                        <CButton color="info" size="sm" style={{ marginLeft: '8px' }} onClick={() => this.startEditingComment(i)} title="Edit comment">✏️</CButton>
                                        <CButton color="danger" size="sm" style={{ marginLeft: '4px' }} onClick={() => this.removeEditComment(i)} title="Remove comment">✕</CButton>
                                    </>
                                )}
                            </li>
                        ))}
                    </ul>
                )}
                <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
                    <CInput placeholder="Add a comment" value={editNewComment}
                        onChange={(e) => this.setState({ editNewComment: e.target.value })}
                        onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); this.addEditComment(); } }} />
                    <CButton color="info" onClick={this.addEditComment}>+ Add</CButton>
                </div>

                <hr />
                <div style={{ display: 'flex', gap: '12px' }}>
                    <CButton color="success" onClick={this.saveChanges}>💾 Save</CButton>
                    <CButton color="secondary" onClick={this.cancelEditing}>Cancel</CButton>
                </div>
            </>
        );
    }
}

const styles = {
    section: { marginBottom: '16px' },
    empty: { color: '#888', fontStyle: 'italic' },
};

export default ViewAction;
